// Combine and filter journalist requests
const twitterResults = $('Search #journorequest').item.json?.data || [];
const qwotedResults = $('Fetch Qwoted Requests').item.json?.requests || [];

const relevantKeywords = [
  'design', 'saas', 'startup', 'subscription', 'agency',
  'landing page', 'conversion', 'branding', 'visual',
  'ai in design', 'design ops', 'freelance', 'creative'
];

const requests = [];

// Process Twitter results
twitterResults.forEach(tweet => {
  const text = tweet.text?.toLowerCase() || '';
  const isRelevant = relevantKeywords.some(kw => text.includes(kw));

  if (isRelevant) {
    requests.push({
      source: 'twitter',
      id: tweet.id,
      text: tweet.text,
      author: tweet.author_id,
      url: `https://twitter.com/i/web/status/${tweet.id}`,
      deadline: null
    });
  }
});

// Process Qwoted results
qwotedResults.forEach(req => {
  const text = (req.title + ' ' + req.description)?.toLowerCase() || '';
  const isRelevant = relevantKeywords.some(kw => text.includes(kw));

  if (isRelevant) {
    requests.push({
      source: 'qwoted',
      id: req.id,
      text: req.title + ': ' + req.description,
      author: req.journalist_name,
      url: req.url || '',
      deadline: req.deadline
    });
  }
});

if (requests.length === 0) {
  return { json: { no_requests: true } };
}

return requests.map(r => ({ json: r }));

